(() => {
  const stage4 = $json || {};
  const jobNode = $('Stage 2: Evaluation Gate (Native Code)').item.json || {};

  // Clean HTML entity encoding like &amp; -> &
  const cleanStr = (s) => (s || '').replace(/&amp;/g, '&');

  const company = cleanStr(jobNode.company || 'Target Company');
  const title = cleanStr(jobNode.title || 'Role');
  const score = jobNode.score != null ? jobNode.score : 85;
  const applyUrl = jobNode.apply_url || jobNode.url || '#';

  const summary = cleanStr(stage4.tailored_summary || 'Tailored specifically for target role requirements.');
  const keywords = Array.isArray(stage4.matched_keywords) ? stage4.matched_keywords.join(', ') : 'Python, TensorFlow, PyTorch, AWS';
  const pdfStatus = stage4.pdf_path ? "✅ `Siddharth_Bhople_Resume.pdf`" : "❌ Not generated";

  return {
    username: "JobApply AI Assistant",
    avatar_url: "https://cdn-icons-png.flaticon.com/512/3855/3855328.png",
    embeds: [
      {
        title: "🎯 Tailored Resume Ready: " + title + " @ " + company,
        url: applyUrl.startsWith('http') ? applyUrl : null,
        color: 3066993,
        fields: [
          { name: "🏢 Company", value: "**" + company + "**", inline: true },
          { name: "💼 Role Title", value: "**" + title + "**", inline: true },
          { name: "📊 Match Score", value: "**" + score + "%**", inline: true },

          { name: "📝 Job-Specific Tailored Summary", value: "*" + summary + "*", inline: false },
          { name: "🔑 Matched Key Skills", value: "`" + keywords + "`", inline: false },
          { name: "📄 Compiled ATS Resume", value: pdfStatus, inline: true },

          {
            name: "🔗 Application Link",
            value: "👉 [**Open Job Posting & Apply**](" + applyUrl + ")",
            inline: false
          }
        ],
        footer: {
          text: "Stage 5 Human-in-the-Loop Approval Gate • JobApply AI Pipeline",
          icon_url: "https://cdn-icons-png.flaticon.com/512/3855/3855328.png"
        }
      }
    ]
  };
})()
}}
